#!/usr/bin/env python3
# Nova Studio — one program file. Runtime JSON/logs live in the user's private data directory.
# Dependencies: python3 -m pip install PyQt6 Appium-Python-Client==6.0.7 cryptography
# Developer commands: python3 NovaStudio.py --help
APP_VERSION = "3.0.0"
UPDATE_MANIFEST_URL = ""
UPDATE_PUBLIC_KEY = ""
UPDATE_GITHUB_REPO = ""

import argparse
import base64
import hashlib
import importlib.abc
import importlib.util
import json
import os
from pathlib import Path
import shutil
import sys
import tempfile
import zlib

# BEGIN EMBEDDED SOURCES
SOURCE_BUNDLE = ""
SOURCE_SHA256 = "3cb134cb05acfaef547d9600118762e5aa6aabe80fb339a75bb53cf40313bb36"
# END EMBEDDED SOURCES
DEVELOPER_HELP = '# NOVA STUDIO 3 — чёрный / лайм + GitHub Updates\n\n## Запуск\nПрограмма — один файл `NovaStudio.py`. Отдельный run_with_telegram.sh не нужен.\nОдин раз установи Python-зависимости:\n```\npython3 -m pip install PyQt6 Appium-Python-Client==6.0.7 cryptography\npython3 NovaStudio.py\n```\nДля работы с физическим iPhone нужны Mac, совместимые Xcode, Appium/XCUITest, WebDriverAgent и доверенный подключённый iPhone. Это приложение не устанавливает их автоматически. Адаптация берёт фактический размер экрана, а не жёстко заданные координаты одной модели. Физические iPhone X–17 Pro Max здесь не проверялись: совместимость зависит также от версии iOS, Instagram, Xcode и WDA.\n\nTelegram запускается вместе с основной программой при настроенном токене и разрешённом Telegram ID. Настройки и секреты сохраняются локально в JSON; никому не отправляй эти JSON. Уже раскрытый токен отзови через BotFather и внеси новый в окно настройки Telegram. Он не включён в архив.\nДанные: Mac `~/Library/Application Support/NovaStudio`; Windows `%APPDATA%/NovaStudio`; Linux `~/.local/share/NovaStudio`. Обновление заменяет только программный .py, не эти данные.\n\n## Настройка GitHub: один раз\n### 1. Репозиторий\nСоздай на GitHub **публичный** репозиторий, например `nova-studio`, с веткой `main`. Эта версия клиента работает с публичными репозиториями без GitHub-токена. Не загружай аккаунты, пароли, Telegram-токен или приватный ключ в репозиторий.\nДобавь содержимое этого архива в корень репозитория, включая **скрытую** папку `.github/workflows/release.yml` и `.gitignore`. Сам ZIP загружать в репозиторий вместо файлов не нужно.\nЕсли работаешь через Git (подставь свой логин):\n```\ngit clone https://github.com/USERNAME/nova-studio.git\n```\nСкопируй файлы архива в полученную папку, затем:\n```\ncd nova-studio\ngit add NovaStudio.py VERSION.txt CHANGELOG.md README.md .gitignore .github/workflows/release.yml\ngit commit -m "NOVA Studio 3: first release"\ngit push origin main\n```\nПри необходимости войди в GitHub через GitHub Desktop или обычную авторизацию Git. Пароль GitHub в программу не нужен.\n\n### 2. Ключ подписи\nОткрой программу → **Обновления → Ключ подписи**. Сохрани приватный ключ **вне папки репозитория**. Сохрани резервную копию в безопасном месте: для будущих выпусков нужен тот же ключ.\nНа GitHub открой репозиторий → **Settings → Secrets and variables → Actions → New repository secret**.\nName: **NOVA_SIGNING_KEY**.\nSecret: содержимое файла приватного ключа (одна Base64-строка). Это не публичный ключ и не Telegram-токен. Не вставляй ключ в код, README или чат.\nWorkflow использует этот secret только при подписании; в приложение попадает только публичный ключ.\nЕсли первый push запустил Action до добавления secret, это нормально: он завершится ошибкой. После настройки запусти вручную следующий шаг.\n\n### 3. Первый выпуск\nGitHub → **Actions → Build signed NOVA release → Run workflow → main → Run workflow**.\nПри необходимости включи Actions; в Settings → Actions → General должны быть разрешены GitHub Actions и создание релизов workflow (Contents: write).\nДождись зелёного статуса. На вкладке **Releases** появится `v3.0.0` с `NovaStudio.py`, `manifest.json`, `NovaStudio.zip`.\nДруг скачивает **NovaStudio.zip из Releases**, не Source code.zip и не исходный архив из чата. В релизном .py уже прописаны твой репозиторий и публичный ключ; вручную настраивать их другу не нужно.\nНе помещай скачанный релиз поверх разработческого файла репозитория: редактируй исходный `NovaStudio.py` из этого архива.\n\n## Как отправить следующее обновление\n1. В приложении **Обновления → Исходники** экспортируй код в пустую рабочую папку вне репозитория.\n2. Отредактируй нужные модули. Через **Собрать .py** собери их обратно в `NovaStudio.py` в репозитории. Другу по-прежнему нужен только этот один .py.\n   Альтернатива из терминала:\n```\npython3 NovaStudio.py --export-sources ../nova-sources\n# отредактируй ../nova-sources/main.py или другой модуль\npython3 NovaStudio.py --build ../nova-sources --output NovaStudio.py\n```\n3. Поменяй `VERSION.txt` с `3.0.0` на `3.0.1` (три числа, без буквы v) и кратко опиши изменения в `CHANGELOG.md`.\n4. Commit и push в `main`:\n```\ngit add NovaStudio.py VERSION.txt CHANGELOG.md\ngit commit -m "Release 3.0.1"\ngit push origin main\n```\n5. Actions проверит код, подпишет файлы, создаст draft, загрузит все файлы и только после этого опубликует релиз. Уже существующий номер не перезаписывается: для нового выпуска увеличивай VERSION.txt.\n6. У друга при открытой программе выполняется фоновая проверка (при старте, затем примерно каждые 6 часов); можно нажать **Проверить версию** сразу. Затем **Установить и перезапустить**.\nАвтоустановка выключена по умолчанию. Друг может включить её; установка ожидает простоя, не прерывает выполняемую или незавершённую задачу и требует отсутствия открытых диалогов/введённых несохранённых паролей. Новая программа перезапустится. Предыдущий .py сохраняется как `.previous.py`.\nИзменение локального кода или обычный push без нового номера версии само по себе не устанавливает обновление другу. Нужно успешное создание Release.\n\n## Проверки и ограничения\nПеред установкой проверяются Ed25519-подпись, SHA-256, размер, номер версии и принадлежность GitHub-релизу. Старые версии и повреждённые файлы отвергаются. Приватные репозитории, beta/prerelease и ветки raw/main не используются. Приватный ключ не отправляется клиенту.\nGitHub API может ограничить частоту запросов; попробуй позже, не отключай проверку подписи. Фоновая работа Telegram продолжается пока работает основное приложение и компьютер не спит. Это не отдельный системный сервис.\nПроверка без реального телефона и без публикаций:\n```\npython3 NovaStudio.py --self-test\npython3 NovaStudio.py --doctor\n```\nВ архиве не настроен реальный репозиторий. Первый опубликованный Release получает адрес автоматически от GitHub Actions. Если сохранял пустые/старые настройки источника в разработческой копии, в поле GitHub укажи свой OWNER/REPO, добавь публичный ключ из `.pub` рядом с приватным ключом и сохрани источник; приватный ключ в это поле не вводи.\n'


def data_directory():
    override=os.environ.get('ORBIT_DATA_DIR')
    if override:return Path(override).expanduser().resolve()
    if sys.platform=='darwin':root=Path.home()/'Library'/'Application Support'
    elif os.name=='nt':root=Path(os.environ.get('APPDATA',str(Path.home()/'AppData'/'Roaming')))
    else:root=Path(os.environ.get('XDG_DATA_HOME',str(Path.home()/'.local'/'share')))
    return root/'NovaStudio'


def source_bank():
    packed=base64.b64decode(SOURCE_BUNDLE)
    if hashlib.sha256(packed).hexdigest()!=SOURCE_SHA256:
        raise RuntimeError('Embedded source integrity failed. Restore the program file.')
    return json.loads(zlib.decompress(packed))


class EmbeddedLoader(importlib.abc.MetaPathFinder,importlib.abc.Loader):
    def __init__(self,sources,directory):self.sources=sources;self.directory=directory
    def find_spec(self,fullname,path=None,target=None):
        if fullname in self.sources:return importlib.util.spec_from_loader(fullname,self)
        return None
    def create_module(self,spec):return None
    def exec_module(self,module):
        module.__file__=str(self.directory/(module.__name__+'.py'))
        module.__package__=''
        exec(compile(self.sources[module.__name__],module.__file__,'exec'),module.__dict__)


def install_modules():
    directory=data_directory();directory.mkdir(mode=0o700,parents=True,exist_ok=True)
    try:os.chmod(directory,0o700)
    except OSError:pass
    sources=source_bank();sys.meta_path.insert(0,EmbeddedLoader(sources,directory))
    os.environ['ORBIT_APP_VERSION']=APP_VERSION
    os.environ['ORBIT_ENTRY_FILE']=str(Path(__file__).resolve())
    os.environ['ORBIT_UPDATE_URL']=UPDATE_MANIFEST_URL
    os.environ['ORBIT_UPDATE_KEY']=UPDATE_PUBLIC_KEY
    os.environ['ORBIT_GITHUB_REPO']=UPDATE_GITHUB_REPO
    os.environ['ORBIT_DEVELOPER_HELP']=DEVELOPER_HELP
    return directory,sources


def migrate_local_settings(directory):
    old=Path(__file__).resolve().parent
    if old==directory:return
    for name in ('bot_settings.json','ui_state.json','.creation_credentials.json','update_settings.json'):
        source=old/name;target=directory/name
        if not target.exists() and source.is_file() and not source.is_symlink() and source.stat().st_size<1024*1024:
            try:
                fd=os.open(target,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
                with os.fdopen(fd,'wb') as file:file.write(source.read_bytes())
            except OSError:pass


def export_sources(directory,sources):
    directory=Path(directory);directory.mkdir(parents=True,exist_ok=True)
    for name in sources:
        target=directory/(name+'.py')
        if target.exists():raise RuntimeError('Export folder already contains '+target.name)
    for name,text in sources.items():
        target=directory/(name+'.py')
        target.write_text(text,encoding='utf-8')
    (directory/'DEVELOPER_HELP.md').write_text(DEVELOPER_HELP,encoding='utf-8')
    print('Exported editable modules. No local credentials were exported.')


def build_file(source_dir,output,sources):
    source_dir=Path(source_dir);updated={}
    for name in sources:
        path=source_dir/(name+'.py')
        if not path.is_file():raise RuntimeError('Missing source module: '+path.name)
        text=path.read_text(encoding='utf-8');compile(text,str(path),'exec');updated[name]=text
    for path in source_dir.glob('*.py'):
        if path.stem.isidentifier() and path.stem not in updated:
            text=path.read_text(encoding='utf-8');compile(text,str(path),'exec');updated[path.stem]=text
    packed=zlib.compress(json.dumps(updated,ensure_ascii=False,sort_keys=True).encode(),9)
    text=Path(__file__).read_text(encoding='utf-8')
    start=text.index('# BEGIN EMBEDDED SOURCES\n');end=text.index('# END EMBEDDED SOURCES',start)
    block='# BEGIN EMBEDDED SOURCES\nSOURCE_BUNDLE = '+repr(base64.b64encode(packed).decode())+'\nSOURCE_SHA256 = '+repr(hashlib.sha256(packed).hexdigest())+'\n'
    text=text[:start]+block+text[end:]
    compile(text,str(output),'exec');Path(output).write_text(text,encoding='utf-8');os.chmod(output,0o700)
    print('Built one program file:',output)


def dependencies_present():
    missing=[]
    for package,install in (('PyQt6','PyQt6'),('appium','Appium-Python-Client==6.0.7'),('cryptography','cryptography')):
        if importlib.util.find_spec(package) is None:missing.append(install)
    if missing:
        raise RuntimeError('Install dependencies once: '+sys.executable+' -m pip install '+' '.join(missing))


def main_entry():
    parser=argparse.ArgumentParser(description='Nova Studio: single-file Instagram desktop automation with signed updates.')
    group=parser.add_mutually_exclusive_group()
    group.add_argument('--export-sources',metavar='DIRECTORY')
    group.add_argument('--build',metavar='SOURCE_DIRECTORY')
    group.add_argument('--init-publisher',metavar='PRIVATE_KEY_FILE')
    group.add_argument('--publish',metavar='APP_FILE')
    group.add_argument('--self-test',action='store_true')
    group.add_argument('--doctor',action='store_true')
    group.add_argument('--apply-update',nargs=2,metavar=('PARENT_PID','STAGED_FILE'),help=argparse.SUPPRESS)
    parser.add_argument('--output',default='release')
    parser.add_argument('--key')
    parser.add_argument('--version')
    parser.add_argument('--release-url')
    parser.add_argument('--manifest-url')
    parser.add_argument('--notes',default='')
    parser.add_argument('--github-repo',default='')
    args=parser.parse_args()
    if args.build:
        build_file(args.build,args.output,source_bank());return
    if args.export_sources:
        export_sources(args.export_sources,source_bank());return
    dependencies_present()
    directory,sources=install_modules()
    if args.doctor:
        for name,text in sources.items():compile(text,name+'.py','exec')
        import main as application
        print('Nova Studio',APP_VERSION,'• single-file sources and dependencies OK')
        print('Modules:',len(sources),'• local data:',directory)
        print('Update source:','configured in file' if (UPDATE_MANIFEST_URL or UPDATE_GITHUB_REPO) and UPDATE_PUBLIC_KEY else 'not configured; use the Updates screen')
        return
    if args.self_test:
        os.environ.setdefault('QT_QPA_PLATFORM','offscreen')
        import unittest
        names=sorted(name for name in sources if name.startswith('test_'))
        suite=unittest.TestLoader().loadTestsFromNames(names)
        result=unittest.TextTestRunner(verbosity=1).run(suite)
        raise SystemExit(0 if result.wasSuccessful() else 1)
    from app_updates import publisher_key,publish_file,apply_after_exit,atomic_json
    if args.init_publisher:
        public=publisher_key(args.init_publisher)
        print('Private key saved locally. Never upload it. Public key:');print(public);return
    if args.publish:
        if not all((args.key,args.version,args.release_url,args.manifest_url)):
            parser.error('--publish requires --key, --version, --release-url and --manifest-url')
        release,manifest,public=publish_file(args.publish,args.key,args.version,args.release_url,args.manifest_url,args.output,args.notes,args.github_repo)
        print('Prepared signed release:',release);print('Manifest:',manifest)
        print('Upload these two files to the configured HTTPS URLs. Public key:');print(public);return
    if args.apply_update:
        try:
            parent=int(args.apply_update[0])
            if parent<=1:raise RuntimeError('Invalid parent process.')
            apply_after_exit(Path(__file__).resolve(),args.apply_update[1],parent,directory,APP_VERSION,UPDATE_PUBLIC_KEY)
            atomic_json(directory/'update_install_status.json',{'ok':True,'message':'Signed update installed.'})
        except Exception:
            atomic_json(directory/'update_install_status.json',{'ok':False,'message':'Update installation failed. The verified backup/current file remains available.'})
            raise
        return
    migrate_local_settings(directory)
    from main import main as run_application
    run_application()


if __name__=='__main__':
    try:main_entry()
    except KeyboardInterrupt:pass
    except Exception as exc:
        print('Nova Studio:',str(exc),file=sys.stderr)
        raise SystemExit(1)
